int solve_dense(int n,const double*M,int k,int*col4row){
  int*adj=malloc((size_t)n*n*sizeof(int));int*deg=calloc(n,sizeof(int));char*in=calloc((size_t)n*n,1);
  int *row4col=malloc(n*sizeof(int)),*path=malloc(n*sizeof(int)),*SRl=malloc(n*sizeof(int)),*SCl=malloc(n*sizeof(int)),*touched=malloc(n*sizeof(int));
  char *SR=calloc(n,1),*SC=calloc(n,1);
  double*sh=malloc(n*sizeof(double)),*u=malloc(n*sizeof(double)),*v=malloc(n*sizeof(double));
  double*tmp=malloc(n*sizeof(double));
  HE*h=malloc(((size_t)n*n+4*n+4)*sizeof(HE));
  if(k>n)k=n;
  int ret=0;
  /* row kNN via threshold */
  for(int i=0;i<n;i++){const double*Mi=M+(size_t)i*n;memcpy(tmp,Mi,n*sizeof(double));qsort(tmp,n,sizeof(double),cmpd);double th=tmp[k-1];
    for(int j=0;j<n;j++)if(Mi[j]<=th&&!in[(size_t)i*n+j]){in[(size_t)i*n+j]=1;adj[(size_t)i*n+deg[i]++]=j;}}
  for(int j=0;j<n;j++){for(int i=0;i<n;i++)tmp[i]=M[(size_t)i*n+j];qsort(tmp,n,sizeof(double),cmpd);double th=tmp[k-1];
    for(int i=0;i<n;i++)if(M[(size_t)i*n+j]<=th&&!in[(size_t)i*n+j]){in[(size_t)i*n+j]=1;adj[(size_t)i*n+deg[i]++]=j;}}
  for(int it=0;it<100;it++){
    ret=lap(n,M,adj,deg,col4row,u,v,row4col,path,SRl,SCl,touched,SR,SC,sh,h);
    if(ret)break;
    int added=0;
    for(int i=0;i<n;i++){const double*Mi=M+(size_t)i*n;double ui=u[i];char*ini=in+(size_t)i*n;
      for(int j=0;j<n;j++){if(Mi[j]-ui-v[j]< -1e-12 && !ini[j]){ini[j]=1;adj[(size_t)i*n+deg[i]++]=j;added++;}}}
    if(!added){ret=0;goto done;}
  }
  ret=-1;
done:
  free(adj);free(deg);free(in);free(row4col);free(path);free(SRl);free(SCl);free(touched);free(SR);free(SC);free(sh);free(u);free(v);free(tmp);free(h);
  return ret;
}
