import os, ctypes
import numpy as np

_lib = ctypes.CDLL(os.path.join(os.path.dirname(os.path.abspath(__file__)), "lsap.so"))
_P = ctypes.c_void_p
_D = ctypes.c_double
_I = ctypes.c_int
