_lib.solve_dense.restype = _I
K = 12
EPS0 = 0.02
EPSF = 1e-7
FAC = 0.2
MAXB = 100


def _fallback(a, b, M):
    import ot
    return ot.lp.emd(a, b, M, check_marginals=False)


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n = a.shape[0]
        if M.shape != (n, n) or n < 2 or b.shape[0] != n:
            return {"transport_plan": _fallback(a, b, M)}
        w = a[0]
        if not ((a == w).all() and (b == w).all()):
            return {"transport_plan": _fallback(a, b, M)}
        mx = M.max(); mn = M.min()
        if not (np.isfinite(mx) and np.isfinite(mn)):
            return {"transport_plan": _fallback(a, b, M)}
        scale = float(mx - mn) or 1.0
        col = np.empty(n, dtype=np.int32)
        ret = _lib.solve_dense(n, M.ctypes.data, int(K), EPS0 * scale, EPSF * scale, FAC, int(MAXB), col.ctypes.data)
        if ret != 0:
            return {"transport_plan": _fallback(a, b, M)}
        P = np.zeros((n, n))
        P[np.arange(n), col] = w
        return {"transport_plan": P}
