import os, ctypes
import numpy as np

_lib = ctypes.CDLL(os.path.join(os.path.dirname(os.path.abspath(__file__)), "lsap2.so"))
_P = ctypes.c_void_p
_D = ctypes.c_double
_I = ctypes.c_int
_lib.solve2.argtypes = [_I, _P, _D, _D, _D, _D, _D, _D, _I, _P]
_lib.solve2.restype = _I
FRAC = 0.08
EPS0 = 0.05
EPSF = 1e-4
FAC = 0.1
FAC2 = 0.01
EPSD = 1e-12
MAXB = 200


def _fallback(a, b, M):
    import ot
    return ot.lp.emd(a, b, M, check_marginals=False)


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n = a.shape[0]
        if M.shape != (n, n) or n < 8 or b.shape[0] != n:
            return {"transport_plan": _fallback(a, b, M)}
        w = a[0]
        if not ((a == w).all() and (b == w).all()):
            return {"transport_plan": _fallback(a, b, M)}
        mx = M.max(); mn = M.min()
        if not (np.isfinite(mx) and np.isfinite(mn)):
            return {"transport_plan": _fallback(a, b, M)}
        scale = float(mx - mn) or 1.0
        samp = M[:: max(1, n // 40)].ravel()
        kk = int(len(samp) * FRAC)
        thr = float(np.partition(samp, kk)[kk])
        col = np.empty(n, dtype=np.int32)
        ret = _lib.solve2(n, M.ctypes.data, thr, EPS0 * scale, EPSF * scale, FAC, FAC2,
                          EPSD * scale, int(MAXB), col.ctypes.data)
        if ret != 0:
            return {"transport_plan": _fallback(a, b, M)}
        P = np.zeros((n, n))
        P[np.arange(n), col] = w
        return {"transport_plan": P}
