import os, ctypes
import numpy as np

_lib = ctypes.CDLL(os.path.join(os.path.dirname(os.path.abspath(__file__)), "lsap2.so"))
_P = ctypes.c_void_p
_D = ctypes.c_double
_I = ctypes.c_int
_lib.solve3.argtypes = [_I, _P, _D, _D, _D, _D, _D, _I, _P]
_lib.solve3.restype = _I
FRAC = 0.08
EPS0 = 0.05
EPSF = 1e-4
FAC = 0.1
TOL = 1e-11
MAXB = 100


def _fallback(a, b, M):
    import ot
    return ot.lp.emd(a, b, M, check_marginals=False)


class Solver:
    def solve(self, problem, **kwargs):
        a = np.asarray(problem["source_weights"], dtype=np.float64)
        b = np.asarray(problem["target_weights"], dtype=np.float64)
        M = np.ascontiguousarray(problem["cost_matrix"], dtype=np.float64)
        n = a.shape[0]
        if M.ndim != 2 or M.shape != (n, n) or n < 8 or b.shape[0] != n:
            return {"transport_plan": _fallback(a, b, M)}
        w = a[0]
        if not ((a == w).all() and (b == w).all()):
            return {"transport_plan": _fallback(a, b, M)}
        col = np.empty(n, dtype=np.int32)
        ret = _lib.solve3(n, M.ctypes.data, FRAC, EPS0, EPSF, FAC, TOL, int(MAXB), col.ctypes.data)
        if ret != 0:
            return {"transport_plan": _fallback(a, b, M)}
        P = np.zeros((n, n))
        P[np.arange(n), col] = w
        return {"transport_plan": P}
